using CrowdFunding.BuildingBlocks.Application.Events;
using CrowdFunding.BuildingBlocks.Infrastructure.Events;
using CrowdFunding.Modules.Campaigns.Infrastructure.Persistence.DbContexts;
using CrowdFunding.Modules.Campaigns.Infrastructure.Transactions;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Npgsql;

#pragma warning disable EF1002 // the table name is generated by the test, never user input

namespace CrowdFunding.IntegrationTests;

/// <summary>
/// The inbox row of a handler that is one transaction is written inside that transaction, so a
/// crash after the handler's commit cannot leave the handler's work done and unrecorded.
/// A handler without the marker keeps the older behaviour (recorded after it ends), shown as the control.
/// </summary>
[Collection(nameof(CampaignsPostgresCollection))]
public sealed class InboxInTransactionTests
{
    private readonly CampaignsPostgresFixture _fixture;

    public InboxInTransactionTests(CampaignsPostgresFixture fixture)
    {
        _fixture = fixture;
    }

    [Fact]
    public async Task CrashAfterTheHandlersCommit_DoesNotRunAMarkedHandlerAgain()
    {
        var probe = await NewProbeAsync();
        await using var provider = BuildProvider(probe);
        var messageId = Guid.NewGuid();

        // The handler commits its work, then the process "dies" before the publisher can record anything.
        probe.CrashAfterCommit = true;
        await Assert.ThrowsAsync<InvalidOperationException>(() => PublishAsync<MarkedEvent>(provider, messageId));
        probe.CrashAfterCommit = false;
        await PublishAsync<MarkedEvent>(provider, messageId);

        Assert.Equal(1, await EffectsAsync(probe));
    }

    [Fact]
    public async Task CrashAfterTheHandlersCommit_RunsAnUnmarkedHandlerAgain_WhichIsWhyItMustBeIdempotent()
    {
        var probe = await NewProbeAsync();
        await using var provider = BuildProvider(probe);
        var messageId = Guid.NewGuid();

        probe.CrashAfterCommit = true;
        await Assert.ThrowsAsync<InvalidOperationException>(() => PublishAsync<UnmarkedEvent>(provider, messageId));
        probe.CrashAfterCommit = false;
        await PublishAsync<UnmarkedEvent>(provider, messageId);

        Assert.Equal(2, await EffectsAsync(probe));
    }

    [Fact]
    public async Task TwoWorkersHandlingTheSameMessageAtOnce_CommitTheHandlersWorkOnce()
    {
        var probe = await NewProbeAsync();
        await using var provider = BuildProvider(probe);
        var messageId = Guid.NewGuid();

        // Both workers pass the "already handled?" check before either has committed.
        probe.HoldBeforeWriting = new Barrier(2);
        await Task.WhenAll(
            PublishAsync<MarkedEvent>(provider, messageId),
            PublishAsync<MarkedEvent>(provider, messageId));

        Assert.Equal(1, await EffectsAsync(probe));
    }

    [Fact]
    public async Task AMarkedHandlerThatWritesNothing_IsStillRecordedAfterwards()
    {
        var probe = await NewProbeAsync();
        await using var provider = BuildProvider(probe);
        var messageId = Guid.NewGuid();
        probe.WriteNothing = true;

        await PublishAsync<MarkedEvent>(provider, messageId);
        await PublishAsync<MarkedEvent>(provider, messageId);

        Assert.Equal(1, probe.Calls);
    }

    private async Task<Probe> NewProbeAsync()
    {
        var probe = new Probe { Table = $"inbox_effects_{Guid.NewGuid():N}" };
        await using var connection = new NpgsqlConnection(_fixture.ConnectionString);
        await connection.OpenAsync();
        await using var command = new NpgsqlCommand($"CREATE TABLE \"{probe.Table}\" (id serial PRIMARY KEY)", connection);
        await command.ExecuteNonQueryAsync();
        return probe;
    }

    private async Task<long> EffectsAsync(Probe probe)
    {
        await using var connection = new NpgsqlConnection(_fixture.ConnectionString);
        await connection.OpenAsync();
        await using var command = new NpgsqlCommand($"SELECT count(*) FROM \"{probe.Table}\"", connection);
        return (long)(await command.ExecuteScalarAsync())!;
    }

    private ServiceProvider BuildProvider(Probe probe)
    {
        var services = new ServiceCollection();
        services.AddSingleton(probe);
        services.AddLogging();
        services.AddDistributedMemoryCache();
        services.AddDbContext<CampaignsDbContext>(o => o.UseNpgsql(_fixture.ConnectionString));
        services.AddScoped<CampaignTransactionExecutor>();
        services.AddScoped<IEventPublisher, ServiceProviderEventPublisher>();
        services.AddScoped<InboxMessageContext>();
        services.AddScoped<IEventHandler<MarkedEvent>, MarkedHandler>();
        services.AddScoped<IEventHandler<UnmarkedEvent>, UnmarkedHandler>();
        services.AddInbox<CampaignsDbContext>(typeof(InboxInTransactionTests).Assembly);
        return services.BuildServiceProvider();
    }

    private static async Task PublishAsync<TEvent>(ServiceProvider provider, Guid messageId)
        where TEvent : BaseApplicationEvent, new()
    {
        await using var scope = provider.CreateAsyncScope();
        scope.ServiceProvider.GetRequiredService<InboxMessageContext>().MessageId = messageId;
        await scope.ServiceProvider.GetRequiredService<IEventPublisher>()
            .PublishAsync(new TEvent(), CancellationToken.None);
    }

    public sealed class MarkedEvent : BaseApplicationEvent
    {
    }

    public sealed class UnmarkedEvent : BaseApplicationEvent
    {
    }

    private sealed class Probe
    {
        public string Table { get; set; } = string.Empty;
        public bool CrashAfterCommit { get; set; }
        public bool WriteNothing { get; set; }
        public Barrier? HoldBeforeWriting { get; set; }
        public int Calls;
    }

    private static async Task DoWorkAsync(Probe probe, CampaignsDbContext db, CampaignTransactionExecutor executor, CancellationToken ct)
    {
        Interlocked.Increment(ref probe.Calls);
        if (!probe.WriteNothing)
        {
            probe.HoldBeforeWriting?.SignalAndWait(TimeSpan.FromSeconds(10));
            await executor.ExecuteAsync(
                async innerCt => await db.Database.ExecuteSqlRawAsync($"INSERT INTO \"{probe.Table}\" DEFAULT VALUES", innerCt),
                ct);
        }

        if (probe.CrashAfterCommit)
        {
            throw new InvalidOperationException("simulated crash after the handler's commit");
        }
    }

    private sealed class MarkedHandler(Probe probe, CampaignsDbContext db, CampaignTransactionExecutor executor)
        : IEventHandler<MarkedEvent>, IRecordsInboxInTransaction
    {
        public Task Handle(MarkedEvent notification, CancellationToken cancellationToken)
            => DoWorkAsync(probe, db, executor, cancellationToken);
    }

    private sealed class UnmarkedHandler(Probe probe, CampaignsDbContext db, CampaignTransactionExecutor executor)
        : IEventHandler<UnmarkedEvent>
    {
        public Task Handle(UnmarkedEvent notification, CancellationToken cancellationToken)
            => DoWorkAsync(probe, db, executor, cancellationToken);
    }
}
